const u = $input.first().json;
const cb = u.callback_query;
const msg = u.message || (cb && cb.message) || {};
const from = (cb ? cb.from : msg.from) || {};
const chat_id = String((msg.chat || {}).id || '');
const user_id = String(from.id || '');
const texto = cb ? '' : (typeof msg.text === 'string' ? msg.text.trim() : '');
let tipo = 'otro';
let comando = '';
if (cb) tipo = 'callback';
else if (texto.startsWith('/')) { tipo = 'comando'; comando = texto.split(/\s+/)[0].split('@')[0].toLowerCase(); }
else if (texto) tipo = 'texto';
const update_id = (u.update_id !== undefined && u.update_id !== null) ? String(u.update_id) : (cb ? 'cb:' + cb.id : 'msg:' + chat_id + ':' + msg.message_id);
return [{ json: {
  update_id: update_id,
  evento_clave: 'upd:' + update_id,
  chat_id: chat_id,
  user_id: user_id,
  texto: texto.slice(0, 4000),
  callback_data: cb ? String(cb.data || '') : '',
  callback_id: cb ? String(cb.id) : '',
  tipo: tipo,
  comando: comando,
} }];

const n = $('Normalizar update').first().json;
const s = $input.first().json || {};
const hay = !!s.session_id;
function pj(v, d) { try { const x = JSON.parse(v || ''); return (x === null || x === undefined) ? d : x; } catch (e) { return d; } }
function item(x) { return typeof x === 'string' ? x : (x && (x.mensaje || x.descripcion)) || JSON.stringify(x); }
function lista(a) { return a.map(function (x) { return '- ' + item(x); }).join('\n'); }
function resumenTexto(ss) {
  const p = pj(ss.parametros_json, {}), u = pj(ss.unidades_json, {});
  const keys = Object.keys(p);
  let t = keys.length ? 'Parámetros registrados:\n' + keys.map(function (k) { return '- ' + k + ': ' + (typeof p[k] === 'object' ? JSON.stringify(p[k]) : p[k]) + (u[k] ? ' ' + u[k] : ''); }).join('\n') : 'Aún no hay parámetros registrados.';
  const sa = pj(ss.supuestos_aceptados_json, []), sp = pj(ss.supuestos_pendientes_json, []), cf = pj(ss.campos_faltantes_json, []), inc = pj(ss.inconsistencias_json, []);
  if (sa.length) t += '\n\nSupuestos aceptados:\n' + lista(sa);
  if (sp.length) t += '\n\nSupuestos pendientes de aceptar:\n' + lista(sp);
  if (cf.length) t += '\n\nDatos faltantes:\n' + lista(cf);
  if (inc.length) t += '\n\nPuntos por aclarar:\n' + lista(inc);
  return t;
}
const START = 'Hola. Soy un asistente para consultar el modelo de aprendizaje automático del proyecto, que predice la respuesta sísmica de pórticos de concreto armado.\n\nCómo funciona:\n1. Escriba /nueva y describa la estructura con sus palabras.\n2. Le pediré los datos que falten (unidades del proyecto: cm, kgf y s).\n3. Revisaré los datos con el servicio de cálculo y le mostraré un resumen para confirmar.\n4. Al confirmar, el modelo calcula 8 respuestas: periodo X/Y (s), cortante basal modal ajustado X/Y (kgf), desplazamiento máximo de azotea X/Y (cm) y deriva máxima X/Y.\n5. Recibirá un informe en PDF.\n\nNo uso valores por defecto sin su aceptación. Las predicciones son estimaciones bajo las hipótesis del proyecto; no constituyen un diseño ni una verificación normativa.\n\nComandos: /nueva, /resumen, /estado, /cancelar.';
const SIN = 'No tiene una consulta activa. Escriba /nueva para empezar.';
const base = { chat_id: n.chat_id, user_id: n.user_id, texto: n.texto, session_id: s.session_id || '', teclado: 'ninguno' };
function r(accion, respuesta, extra) { return [{ json: Object.assign({}, base, { accion: accion, respuesta: respuesta }, extra || {}) }]; }
const enProceso = ['procesando', 'prediccion_completada'].includes(s.estado);

if (n.tipo === 'otro') return r('responder', 'Solo puedo procesar mensajes de texto y los botones del bot.');

if (n.tipo === 'comando') {
  const c = n.comando;
  if (c === '/start') return r('responder', START);
  if (c === '/nueva') {
    const sid = n.chat_id + '-' + n.user_id + '-' + Date.now();
    const preg = '¿Cuántos pisos tiene la estructura y cuál es la altura de cada piso? Indique la unidad (por ejemplo: 3 pisos de 300 cm).';
    return r('nueva', 'Nueva consulta iniciada.' + (hay && enProceso ? ' La consulta anterior sigue calculándose y le llegará su informe.' : '') + '\n\n' + preg, { session_id: sid, pregunta_actual: preg });
  }
  if (!hay) return r('responder', SIN);
  if (c === '/resumen') return r('responder', 'Consulta ' + s.session_id + '\n\n' + resumenTexto(s));
  if (c === '/cancelar') return r('cancelar', 'Consulta cancelada. Sus datos no se borraron. Escriba /nueva para empezar otra.' + (enProceso ? ' Si el cálculo ya se había iniciado, puede que aún reciba el informe.' : ''));
  if (c === '/estado') {
    let t = 'Estado de la consulta ' + s.session_id + ':\n- Conversación: ' + (s.estado || '-') + '\n- Cálculo: ' + (s.estado_procesamiento || 'sin iniciar') + '\n- Informe: ' + (s.entrega_estado || 'sin generar');
    if (s.prediccion_completada === true && String(s.entrega_estado || '').startsWith('error')) {
      return r('lanzar_procesamiento', t + '\n\nLa predicción ya está calculada. Reintento solo la generación y entrega del informe.');
    }
    if (s.confirmado === true && s.estado_procesamiento === 'error' && s.prediccion_completada !== true) {
      const rv = pj(s.resumen_validado_json, {});
      return r('reabrir_confirmacion', t + '\n\nEl cálculo no pudo completarse. Sus datos siguen guardados. Puede confirmar de nuevo:\n\n' + (rv.resumen_legible || resumenTexto(s)), { teclado: 'confirmar' });
    }
    return r('responder', t);
  }
  return r('responder', 'Comando no reconocido. Comandos disponibles: /start, /nueva, /resumen, /estado, /cancelar.');
}

if (n.tipo === 'callback') {
  const partes = n.callback_data.split(':');
  const acc = partes[0];
  const sid = partes.slice(1).join(':');
  if (!hay || sid !== s.session_id) return r('responder', 'Este botón pertenece a una consulta anterior o cancelada. Use /estado o /nueva.');
  if (acc === 'cancelar') return r('cancelar', 'Consulta cancelada. Sus datos no se borraron. Escriba /nueva para empezar otra.');
  if (acc === 'confirmar') {
    if (enProceso || s.confirmado === true) return r('responder', 'Su consulta ya fue enviada y está en proceso. Use /estado para ver el avance.');
    if (s.estado !== 'esperando_confirmacion') return r('responder', 'Los datos cambiaron después de ese resumen. Termine de completarlos y le mostraré un resumen nuevo para confirmar.');
    return r('confirmar', 'Consulta confirmada y enviada al servicio de cálculo. Le avisaré cuando el informe esté listo; mientras tanto puede usar /estado.', { evento_confirm: 'confirm:' + s.session_id + ':' + (s.confirmado_en || '0') });
  }
  if (enProceso) return r('responder', 'La consulta ya está en cálculo y no puede modificarse. Use /nueva para otra estructura.');
  if (acc === 'modificar') return r('modificar', 'De acuerdo. Indique qué dato desea cambiar; los demás se conservan.');
  if (acc === 'aceptar_supuestos') {
    const sp = pj(s.supuestos_pendientes_json, []);
    if (!sp.length) return r('responder', 'No hay supuestos pendientes de aceptar.');
    const sa = pj(s.supuestos_aceptados_json, []).concat(sp);
    return r('aceptar_supuestos', 'Supuestos aceptados. Reviso los datos con el servicio de cálculo...', { supuestos_aceptados_json: JSON.stringify(sa) });
  }
  return r('responder', 'Botón no reconocido.');
}

// Texto libre
if (!hay) return r('responder', SIN);
if (enProceso) return r('responder', 'Su consulta se está calculando. Use /estado para ver el avance o /nueva para otra estructura.');
if (s.estado === 'completada') return r('responder', 'Esta consulta ya terminó. Escriba /nueva para consultar otra estructura.');
const contexto = {
  parametros_registrados: pj(s.parametros_json, {}),
  unidades_registradas: pj(s.unidades_json, {}),
  supuestos_aceptados: pj(s.supuestos_aceptados_json, []),
  supuestos_pendientes: pj(s.supuestos_pendientes_json, []),
  campos_faltantes: pj(s.campos_faltantes_json, []),
  inconsistencias: pj(s.inconsistencias_json, []),
  pregunta_actual: s.pregunta_actual || '',
  ultimos_turnos: pj(s.historial_json, []).slice(-6),
};
return r('extraer', '', { sesion: s, contexto_ia: JSON.stringify(contexto) });

const n = $('Normalizar update').first().json;
const d = $('Decidir acción').first().json;
function ran(name) { try { return $(name).isExecuted; } catch (e) { return false; } }
let src = d;
if (ran('Mensaje de fallo')) src = $('Mensaje de fallo').first().json;
else if (ran('Interpretar validación')) src = $('Interpretar validación').first().json;
else if (ran('Texto ya en proceso')) src = $('Texto ya en proceso').first().json;
else if (ran('Validar extracción')) src = $('Validar extracción').first().json;
function esc(t) { return String(t || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }
return [{ json: { chat_id: n.chat_id, session_id: d.session_id, texto: esc(src.respuesta || 'No tengo una respuesta para ese mensaje. Use /start para ver los comandos.').slice(0, 4000), teclado: src.teclado || 'ninguno' } }];

