const d = $('Decidir acción').first().json;
const s = d.sesion || {};
const schema = $('Obtener esquema del modelo').first().json || {};
const out = ($input.first().json || {}).output;
function pj(v, dd) { try { const x = JSON.parse(v || ''); return (x === null || x === undefined) ? dd : x; } catch (e) { return dd; } }
function item(x) { return typeof x === 'string' ? x : JSON.stringify(x); }
let campos = schema.campos || schema.fields || schema.parametros || schema.properties || [];
const def = {};
if (Array.isArray(campos)) campos.forEach(function (c) { const nm = c && (c.nombre || c.name || c.id); if (nm) def[nm] = c; });
else if (campos && typeof campos === 'object') Object.keys(campos).forEach(function (k) { def[k] = campos[k] || {}; });
const errores = [];
const ESTADOS = ['faltan_datos', 'requiere_aclaracion', 'listo_para_validar'];
if (!out || typeof out !== 'object') errores.push('salida vacía');
else {
  if (!ESTADOS.includes(out.estado)) errores.push('estado inválido');
  ['parametros', 'unidades'].forEach(function (k) { if (!out[k] || typeof out[k] !== 'object' || Array.isArray(out[k])) errores.push(k + ' no es objeto'); });
  ['supuestos_pendientes', 'campos_faltantes', 'inconsistencias'].forEach(function (k) { if (!Array.isArray(out[k])) errores.push(k + ' no es lista'); });
  if (typeof out.siguiente_pregunta !== 'string') errores.push('siguiente_pregunta no es texto');
}
if (!Object.keys(def).length) errores.push('el esquema del servicio no define campos');
if (errores.length) {
  return [{ json: { valido: false, listo: false, teclado: 'ninguno', detalle: errores.join('; '), respuesta: 'No pude interpretar su mensaje con seguridad. ¿Podría reformularlo indicando los valores y sus unidades?' } }];
}
const SIN_UNIDAD = ['', 'adimensional', '-', 'none'];
const aceptados = {}, unidadesAcept = {}, rechazados = [];
Object.keys(out.parametros).forEach(function (k) {
  const v = out.parametros[k];
  if (v === null || v === undefined || v === '') return;
  const f = def[k];
  if (!f) { rechazados.push('"' + k + '" no es un parámetro admitido por el modelo.'); return; }
  const uReq = String(f.unidad !== undefined ? f.unidad : (f.unit !== undefined ? f.unit : '')).trim();
  const uDada = out.unidades[k] ? String(out.unidades[k]).trim() : '';
  if (!SIN_UNIDAD.includes(uReq.toLowerCase())) {
    if (!uDada) { rechazados.push('Falta la unidad de "' + k + '" (el modelo usa ' + uReq + ').'); return; }
    if (uDada.toLowerCase() !== uReq.toLowerCase()) { rechazados.push('"' + k + '" está en ' + uDada + ' y el modelo usa ' + uReq + '. Indique el valor en ' + uReq + '.'); return; }
  }
  const ops = f.opciones || f.options || f.enum;
  if (Array.isArray(ops) && ops.length && !ops.map(String).includes(String(v))) { rechazados.push('"' + k + '" debe ser una de estas opciones: ' + ops.join(', ') + '.'); return; }
  const mn = f.min !== undefined ? f.min : f.minimo, mx = f.max !== undefined ? f.max : f.maximo;
  if (typeof v === 'number' && ((mn !== undefined && mn !== null && v < mn) || (mx !== undefined && mx !== null && v > mx))) { rechazados.push('"' + k + '" = ' + v + ' está fuera del rango admitido (' + (mn !== undefined ? mn : '-') + ' a ' + (mx !== undefined ? mx : '-') + ').'); return; }
  aceptados[k] = v;
  if (uDada) unidadesAcept[k] = uDada;
});
const parametros = Object.assign({}, pj(s.parametros_json, {}), aceptados);
const unidades = Object.assign({}, pj(s.unidades_json, {}), unidadesAcept);
const inconsistencias = out.inconsistencias.concat(rechazados);
const sp = out.supuestos_pendientes;
let estado = out.estado;
if (rechazados.length && estado === 'listo_para_validar') estado = 'requiere_aclaracion';
const listo = estado === 'listo_para_validar' && !sp.length && !out.campos_faltantes.length && !inconsistencias.length;
let respuesta = '';
let teclado = 'ninguno';
if (listo) respuesta = 'Tengo todos los datos. Los estoy revisando con el servicio de cálculo...';
else {
  if (rechazados.length) respuesta += 'No registré estos datos:\n' + rechazados.map(function (x) { return '- ' + x; }).join('\n') + '\n\n';
  if (sp.length) { respuesta += 'Propongo estos supuestos; solo los usaré si los acepta:\n' + sp.map(function (x) { return '- ' + item(x); }).join('\n') + '\n\n'; teclado = 'supuestos'; }
  respuesta += out.siguiente_pregunta || '¿Qué dato desea indicar a continuación?';
}
const hist = pj(s.historial_json, []);
hist.push({ u: String(d.texto || '').slice(0, 1000), b: respuesta.slice(0, 1000), t: new Date().toISOString() });
return [{ json: {
  valido: true,
  listo: listo,
  teclado: teclado,
  respuesta: respuesta,
  estado: listo ? 'validando' : (estado === 'requiere_aclaracion' ? 'requiere_aclaracion' : 'recopilando'),
  parametros_json: JSON.stringify(parametros),
  unidades_json: JSON.stringify(unidades),
  supuestos_pendientes_json: JSON.stringify(sp),
  campos_faltantes_json: JSON.stringify(out.campos_faltantes),
  inconsistencias_json: JSON.stringify(inconsistencias),
  pregunta_actual: out.siguiente_pregunta || '',
  historial_json: JSON.stringify(hist.slice(-10)),
} }];

const r = $input.first().json || {};
const s = $('Releer sesión').first().json || {};
function arr(x) { return Array.isArray(x) ? x : (x ? [x] : []); }
function item(x) { return typeof x === 'string' ? x : (x && (x.mensaje || x.message || x.descripcion)) || JSON.stringify(x); }
function fmt(a) { return a.map(function (x) { return '- ' + item(x); }).join('\n'); }
function resumenLocal() {
  let p = {}, u = {};
  try { p = JSON.parse(s.parametros_json || '{}'); u = JSON.parse(s.unidades_json || '{}'); } catch (e) {}
  return Object.keys(p).map(function (k) { return '- ' + k + ': ' + (typeof p[k] === 'object' ? JSON.stringify(p[k]) : p[k]) + (u[k] ? ' ' + u[k] : ''); }).join('\n');
}
const errores = arr(r.errores), acl = arr(r.aclaraciones), sup = arr(r.supuestos_propuestos), sec = arr(r.secciones_propuestas);
const puntos = errores.concat(acl);
let o = { resultado: 'aclaracion', teclado: 'ninguno', estado: 'requiere_aclaracion', supuestos_pendientes_json: s.supuestos_pendientes_json || '[]', inconsistencias_json: JSON.stringify(puntos), resumen_validado_json: '' };
if (r.fuera_de_dominio) {
  const det = typeof r.fuera_de_dominio === 'string' ? r.fuera_de_dominio : fmt(puntos);
  o.respuesta = 'El modelo actual no puede predecir esta estructura: está fuera del dominio de los datos con que fue entrenado.' + (det ? '\n' + det : '') + '\n\nIndique una alternativa dentro del alcance o revise los datos con /resumen.';
} else if (puntos.length) {
  o.respuesta = 'El servicio de cálculo encontró puntos por resolver:\n' + fmt(puntos) + '\n\nIndique la corrección; sus demás datos siguen guardados.';
} else if (sup.length || sec.length) {
  const prop = sup.concat(sec.map(function (x) { return 'Sección propuesta: ' + item(x); }));
  o = Object.assign(o, { resultado: 'supuestos', teclado: 'supuestos', estado: 'recopilando', supuestos_pendientes_json: JSON.stringify(prop), inconsistencias_json: '[]', respuesta: 'El servicio propone estos supuestos o secciones. Solo se usarán si los acepta:\n' + fmt(prop) });
} else if (r.valido === true) {
  o = Object.assign(o, { resultado: 'valido', teclado: 'confirmar', estado: 'esperando_confirmacion', supuestos_pendientes_json: '[]', inconsistencias_json: '[]', resumen_validado_json: JSON.stringify(r), respuesta: 'Resumen de la estructura validada:\n\n' + (r.resumen_legible || resumenLocal()) + '\n\n¿Confirma estos datos para calcular la predicción?' });
} else {
  o.respuesta = 'El servicio no pudo validar los datos. Revise el resumen con /resumen e indique correcciones.';
}
return [{ json: o }];
